const results=[];
for (const [i,item] of $input.all().entries()) {
 const j=item.json;
 if (j['Upload ID'] !== undefined) {
  const keys=Object.keys(item.binary || {}), source=String(j['Upload ID']).trim();
  if (keys.length!==1 || !source || source.length>200) throw new Error('One file and a valid Upload ID are required.');
  results.push({json:{source_type:'upload',source_namespace:'n8n-ap-upload-v1',source_id:source,attachment_id:'0',batch_id:'upload-'+$execution.id,case_id:'upload',notification_mode:'batch',auto_approval_limit_eur:String(j.auto_approval_limit_eur)},binary:{data:item.binary[keys[0]]},pairedItem:{item:i}});continue;
 }

 const match=String(j.subject || '').match(/^\[AP-DEMO\]\[([A-Za-z0-9_-]{1,80})\]\[([A-Za-z0-9_-]{1,80})\]/);
 if (!match || !j.id) throw new Error('Expected a batch-tagged email with a provider message ID.');
 const keys=Object.keys(item.binary || {});
 for (const key of keys.length?keys:['none']) {
  const b=item.binary?.[key];
  const supported=Boolean(b && ['application/pdf','image/png','image/jpeg'].includes(b.mimeType));
  results.push({json:{source_type:'email',source_namespace:'gmail:ap-test-inbox',source_id:String(j.id),attachment_id:key,batch_id:match[1],case_id:match[2],notification_mode:'batch',auto_approval_limit_eur:String(j.auto_approval_limit_eur)},binary:{data:b || {data:'',mimeType:'application/x-ap-no-attachment',fileName:'no-attachment'}},pairedItem:{item:i}});
 }
}
return results;
